import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        cur = start_date
        step = timedelta(days=k)
        while len(result) < count:
            result.append(cur.isoformat())
            cur += step
        return result

    wd_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}

    if freq == "WEEKLY":
        days = sorted(wd_map[d] for d in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(result) < count:
            monday = week0_monday + timedelta(weeks=w * k)
            for offset in days:
                d = monday + timedelta(days=offset)
                if d >= start_date:
                    result.append(d.isoformat())
                    if len(result) == count:
                        break
            w += 1
        return result

    if freq == "MONTHLY":
        m_idx = 0
        if len(parts) == 3:
            day_spec = int(parts[2])
            while len(result) < count:
                total_months = (start_date.year * 12 + (start_date.month - 1)) + m_idx * k
                year, month0 = divmod(total_months, 12)
                month = month0 + 1
                num_days = calendar.monthrange(year, month)[1]
                day = num_days if day_spec == -1 else day_spec
                if 1 <= day <= num_days:
                    d = date(year, month, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m_idx += 1
        else:
            n = int(parts[2])
            target_wd = wd_map[parts[3]]
            while len(result) < count:
                total_months = (start_date.year * 12 + (start_date.month - 1)) + m_idx * k
                year, month0 = divmod(total_months, 12)
                month = month0 + 1
                first_wd, num_days = calendar.monthrange(year, month)
                if n == -1:
                    last_wd = (first_wd + num_days - 1) % 7
                    day = num_days - (last_wd - target_wd) % 7
                else:
                    first_day = 1 + (target_wd - first_wd) % 7
                    day = first_day + (n - 1) * 7
                if 1 <= day <= num_days:
                    d = date(year, month, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m_idx += 1
        return result

    if freq == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        y_idx = 0
        while len(result) < count:
            year = start_date.year + y_idx * k
            num_days = calendar.monthrange(year, mm)[1]
            if dd <= num_days:
                d = date(year, mm, dd)
                if d >= start_date:
                    result.append(d.isoformat())
            y_idx += 1
        return result

    raise ValueError(f"Unsupported rule: {rule}")
